/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	return {
		propName: "enable_auto_resolution",
		value: event.payload.value
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	const enableAutoResolution = api.state.enable_auto_resolution;
    const enableAutoResolutionConfigRecord = api.data.look_up_enable_auto_resolution_record.results[0];
    if (enableAutoResolution == enableAutoResolutionConfigRecord.value.displayValue)
        return {};

    const recordId = enableAutoResolutionConfigRecord._row_data.uniqueValue;
    const fieldVlaues = 'value=' + enableAutoResolution;

	return {
		table: 'sys_properties',
        recordId: recordId,
        templateFields: fieldVlaues,
        useSetDisplayValue: null
	};
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function evaluateEvent({
    api,
    event
}) {
    const {
        table
    } = event.payload;
    const _route = 'record';
    const _fields = {
        'table': table,
        'sysId': -1
    };
    const _params = {
        't': Date.now()
    };
    return {
        route: _route,
        fields: _fields,
        params: _params,
        redirect: null,
        passiveNavigation: null,
        title: null,
        multiInstField: null,
        targetRoute: null,
        external: null
    };
}
